def build_and_test(tag, src, user, pswd):
    open('/app/main.go','w').write(src)
    r = subprocess.run(['go','build','-o','/app/admin-tool','/app/main.go'], capture_output=True, text=True)
    assert r.returncode==0, (tag, r.stderr[-2000:])
    subprocess.run(['rm','-f','/app/output.txt'])
    r2 = subprocess.run(['python3','/app/solve_challenge.py'], capture_output=True, text=True, timeout=120)
    ok = r2.returncode==0 and os.path.exists('/app/output.txt')
    # verify creds actually work
    r3 = subprocess.run(['/app/admin-tool','-username',user,'-password',pswd], capture_output=True, text=True)
    print(f"{tag}: solver_exit={r2.returncode} output_exists={ok} truecreds_exit={r3.returncode}")
    tail = '\n'.join(r2.stdout.strip().split('\n')[-4:])
    print('   '+tail.replace('\n',' | '))
